109	/* user virtual address window reserved for shared pages: it stops right
110	 * below the first page a user ELF is linked at (its headers live at 0xf000) */
111	#define SHM_VA_BEGIN 0x1000lu
112	#define SHM_VA_END   0xf000lu
113	
114	/* the image of a user program, headers included, and the first page of its
115	 * stack are mapped when the address space is created */
116	#define USER_CODE_BEGIN 0xf000lu
117	#define USER_CODE_END   0x14000lu
