101	static inline void clear_pgdir(PTE* pgdir_addr)
102	{
103	    memset(pgdir_addr, 0, 4096);
104	}
105	
106	/* Get/Set page frame number of the `entry` */
107	static inline long get_pfn(PTE entry)
108	{
109	    return ((entry >> _PAGE_PFN_SHIFT) & PFN_MASK);
110	}
111	static inline void set_pfn(PTE *entry, uint64_t pfn)
112	{
113	    *entry = *entry & ATTRIBUTE_MASK;
114	    *entry = *entry | (pfn << _PAGE_PFN_SHIFT);
115	}
116	static inline uintptr_t get_pa(PTE entry)
117	{
118	    return (((entry >> _PAGE_PFN_SHIFT) & PFN_MASK) << NORMAL_PAGE_SHIFT);
119	}
120	
121	/* Get/Set/Clear attribute(s) of the `entry` */
122	static inline long get_attribute(PTE entry, uint64_t mask)
123	{
124	    return ((entry & mask) != 0);
125	}
126	static inline void set_attribute(PTE *entry, uint64_t bits)
127	{
128	    *entry = *entry | bits;
129	}
130	static inline void clear_attribute(PTE *entry, uint64_t bits)
131	{
132	    *entry = *entry & ~bits;
133	}
